import {
  Activity, AlertTriangle, ArrowLeft, BarChart3, Bell, Check, CheckCircle2,
  ChevronRight, CirclePlus, ClipboardCheck, Clock3, ExternalLink, FileText, Home,
  LogOut, Map, MapPin, MessageSquare, Navigation,
  Phone, Radio, RefreshCw, Search, Settings, Shield, SlidersHorizontal,
  X, Zap,
} from 'lucide-react';

const responderAccount = { email: 'rescuer@test.com', password: 'rescuer123', name: 'Delos Reyes', role: 'rescuer', id: 'RSP-014' };

const seedReports = [
  {
    id: 'EM-001', type: 'Flood Rescue', location: 'Purok 2, Barangay Camunatan', landmark: 'Near the covered court', priority: 'High', status: 'On the way', assignedAt: 'Sep 06, 2026 · 08:45 AM', contact: '0912 345 6789', contactName: 'Juan Dela Cruz', description: 'Water level rising fast. Family of 5 reported trapped on the second floor.', assessment: 'Water is above knee level; rescue boat recommended.', team: 'Rescue Team Alpha', purok: 'Purok 2', emergency: true, score: 6,
    history: [{ status: 'Assigned', by: 'Admin Delos Reyes', time: 'Sep 06 · 08:45 AM' }, { status: 'On the way', by: 'Delos Reyes', time: 'Sep 06 · 08:51 AM' }],
    checklist: { 'Contact person reached': true, 'Location confirmed': true },
  },
  {
    id: 'EM-002', type: 'Medical Emergency', location: 'Purok 3, Barangay Camunatan', landmark: 'Beside the sari-sari store', priority: 'High', status: 'Arrived at location', assignedAt: 'Sep 06, 2026 · 07:20 AM', contact: '0912 987 6543', contactName: 'Maria Dela Cruz', description: 'Elderly resident experiencing difficulty breathing.', assessment: 'Patient is conscious. Hospital transport may be needed.', team: 'Health Response Unit', purok: 'Purok 3', emergency: true, score: 5,
    history: [{ status: 'Assigned', by: 'Admin Delos Reyes', time: 'Sep 06 · 07:20 AM' }, { status: 'Arrived at location', by: 'Delos Reyes', time: 'Sep 06 · 07:42 AM' }],
    checklist: { 'Contact person reached': true, 'Location confirmed': true, 'Arrived at area': true, 'Safety checked': true },
  },
  {
    id: 'NE-003', type: 'Evacuation Assistance', location: 'Purok 1, Barangay Camunatan', landmark: 'Blue house with red gate', priority: 'Medium', status: 'Assistance provided', assignedAt: 'Sep 05, 2026 · 06:10 PM', contact: '0917 222 1100', contactName: 'Rosa Santos', description: 'Family needs help moving to the evacuation center before the typhoon.', assessment: 'Two seniors and one child need transport.', team: 'Barangay Transport', purok: 'Purok 1', emergency: false, score: 4,
    history: [{ status: 'Assigned', by: 'Admin Delos Reyes', time: 'Sep 05 · 06:10 PM' }, { status: 'Assistance provided', by: 'Delos Reyes', time: 'Sep 05 · 07:05 PM' }],
    checklist: { 'Contact person reached': true, 'Location confirmed': true, 'Arrived at area': true, 'Safety checked': true, 'Assistance provided': true, 'Evacuation assisted': true },
  },
  {
    id: 'NE-004', type: 'Road Obstruction', location: 'Purok 1, Barangay Camunatan', landmark: 'Near the elementary school', priority: 'Low', status: 'Assigned', assignedAt: 'Sep 05, 2026 · 02:30 PM', contact: '0918 555 2010', contactName: 'Camunatan Elementary', description: 'A large mango branch fell across the road after the storm.', assessment: 'Chainsaw and cleanup crew needed.', team: 'Public Works', purok: 'Purok 1', emergency: false, score: 2,
    history: [{ status: 'Assigned', by: 'Admin Delos Reyes', time: 'Sep 05 · 02:30 PM' }], checklist: {},
  },
];

const updateOptions = ['On the way', 'Arrived at location', 'Contacted resident', 'Assistance provided', 'Needs additional support', 'Resolved', 'Unable to locate', 'False/invalid after checking'];
const checklistItems = ['Contact person reached', 'Location confirmed', 'Arrived at area', 'Safety checked', 'Assistance provided', 'Evacuation assisted', 'Medical help requested', 'Hotline contacted', 'Report resolved'];
const priorityChecks = ['Life at risk', 'Trapped person', 'Water above knee', 'Fire/electrical risk', 'Medical help needed', 'Immediate evacuation', 'Child/senior/PWD/pregnant affected', 'Multiple people affected'];
const hotlines = { 'Flood Rescue': ['CDRRMO / Rescue', '911'], 'Medical Emergency': ['Hospital / Ambulance', '911'], 'Public Safety': ['Police', '117'], 'Evacuation Assistance': ['Barangay Officials / CDRRMO', '0917 555 0111'], 'Road Obstruction': ['Barangay Public Works', '0917 555 0111'] };

function formatNow() { return new Date().toLocaleString('en-PH', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }); }
function priorityClass(priority) { return priority === 'High' ? 'bg-red-50 text-red-700 border-red-100' : priority === 'Medium' ? 'bg-amber-50 text-amber-700 border-amber-100' : 'bg-slate-100 text-slate-600 border-slate-200'; }
function statusClass(status) { return ['Resolved', 'Assistance provided'].includes(status) ? 'bg-emerald-50 text-emerald-700' : status === 'Needs additional support' ? 'bg-red-50 text-red-700' : 'bg-blue-50 text-blue-700'; }

export default function ResponderApp() {
  const [user, setUser] = useState(null);
  const [reports, setReports] = useState(seedReports);
  const [screen, setScreen] = useState('dashboard');
  const [selectedId, setSelectedId] = useState(null);
  const [reportReturnScreen, setReportReturnScreen] = useState('assigned');
  const [modal, setModal] = useState(null);
  const [notice, setNotice] = useState('');
  const selectedReport = reports.find((report) => report.id === selectedId) || reports[0];

  const openReport = (reportId, nextScreen = 'details', returnScreen = 'assigned') => { setSelectedId(reportId); setReportReturnScreen(returnScreen); setScreen(nextScreen); };
  const showNotice = (message) => { setNotice(message); window.setTimeout(() => setNotice(''), 2600); };
  const saveUpdate = (status, remarks, proof) => {
    if (!remarks.trim()) return false;
    const stamp = formatNow();
    setReports((current) => current.map((report) => report.id === selectedReport.id ? { ...report, status, proof: proof || report.proof, lastRemark: remarks, history: [...report.history, { status, by: user.name, time: stamp, remarks }] } : report));
    setModal(null); setScreen('details'); showNotice('Progress update saved for admin review.'); return true;
  };
  const toggleChecklist = (item) => setReports((current) => current.map((report) => report.id === selectedReport.id ? { ...report, checklist: { ...report.checklist, [item]: report.checklist[item] ? undefined : { by: user.name, time: formatNow() } } } : report));
  const login = (email, password) => {
    const registered = JSON.parse(localStorage.getItem('resqnow_registered_responder') || 'null');
    const account = email === responderAccount.email && password === responderAccount.password
      ? responderAccount
      : registered?.email === email && registered?.password === password
        ? registered
        : null;
    if (!account) return false;
    localStorage.setItem('resqnow_responder', JSON.stringify(account)); setUser(account); setScreen('dashboard'); return true;
  };

  if (!user) return <ResponderAuth onLogin={login} />;

  return <div className="responder-shell min-h-screen bg-slate-50 pb-24">
    <header className="sticky top-0 z-40 border-b border-slate-200 bg-white shadow-sm">
      <div className="mx-auto flex h-16 max-w-lg items-center justify-between px-4">
        <button type="button" onClick={() => setScreen('dashboard')} className="flex items-center gap-2.5 text-left">
          <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-resqnow-red shadow-sm"><Shield className="h-5 w-5 text-white" /></div>
          <div><p className="text-[15px] font-bold leading-tight text-slate-900">ResQNow</p><p className="text-[10px] text-slate-500">Barangay Camunatan</p></div>
        </button>
        <button type="button" onClick={() => setScreen('notifications')} className="flex items-center gap-2.5">
          <div className="text-right"><p className="text-[11px] text-slate-500">Hello,</p><p className="max-w-[110px] truncate text-[12px] font-semibold text-slate-800">{user.name}</p></div>
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-gradient-to-br from-teal-500 to-blue-600 text-[13px] font-bold text-white shadow-sm">DR</div>
        </button>
      </div>
    </header>
    <main className="responder-content mx-auto max-w-lg">
      {notice && <div className="fixed left-1/2 top-20 z-50 flex -translate-x-1/2 items-center gap-2 rounded-xl bg-slate-900 px-4 py-3 text-xs font-semibold text-white shadow-xl"><CheckCircle2 className="h-4 w-4 text-emerald-400" />{notice}</div>}
      {screen === 'dashboard' && <><Dashboard reports={reports} user={user} openReport={openReport} setScreen={setScreen} /><DashboardMapOverview reports={reports} openReport={openReport} /></>}
      {screen === 'assigned' && <AssignedReports reports={reports} openReport={openReport} setScreen={setScreen} />}
      {screen === 'details' && <ReportDetails report={selectedReport} setScreen={(nextScreen) => setScreen(nextScreen === 'assigned' ? reportReturnScreen : nextScreen)} openModal={setModal} toggleChecklist={toggleChecklist} />}
      {screen === 'map' && <MapView reports={reports} selectedId={selectedId} openReport={openReport} />}
      {screen === 'respond' && <RespondScreen reports={reports} openReport={openReport} />}
      {screen === 'notifications' && <InteractiveNotifications openReport={openReport} />}
      {screen === '__legacy_notifications__' && <Notifications openReport={openReport} />}
      {screen === 'settings' && <ResponderSettings user={user} onLogout={() => { localStorage.removeItem('resqnow_responder'); setScreen('dashboard'); setUser(null); }} />}
      {screen === '__admin_removed__' && <AdminSupport reports={reports} showNotice={showNotice} />}
      {screen === '__legacy_sidebar__' && <ResponderSidebar screen={screen} setScreen={setScreen} onLogout={() => setUser(null)} />}
    </main>
    <ResponderBottomNav screen={screen} setScreen={setScreen} />
    {modal === 'update' && <UpdateModal report={selectedReport} onClose={() => setModal(null)} onSave={saveUpdate} />}
  </div>;
}

function ResponderAuth({ onLogin }) {
  const [mode, setMode] = useState('login');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('rescuer@test.com');
  const [password, setPassword] = useState('rescuer123');
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');

  const submit = (event) => {
    event.preventDefault();
    setError('');
    setMessage('');
    if (mode === 'login') {
      if (!onLogin(email, password)) setError('The email or password is incorrect.');
      return;
    }
    if (!name.trim() || !email.trim() || !password.trim()) {
      setError('Name, email, and password are required.');
      return;
    }
    const account = { id: 'RSP-NEW', name: name.trim(), email: email.trim(), password, role: 'rescuer' };
    localStorage.setItem('resqnow_registered_responder', JSON.stringify(account));
    setMode('login');
    setPassword('');
    setMessage('Account created. Sign in to open the field dashboard.');
  };

  if (mode === '__legacy__') return <ResponderLogin onLogin={onLogin} />;

  return <div className="responder-shell flex min-h-screen items-center justify-center bg-cover bg-center p-4" style={{ backgroundImage: 'linear-gradient(120deg, rgba(15,118,110,.88), rgba(30,58,95,.86)), url(https://images.unsplash.com/photo-1580674684081-7617fbf3d745?w=1600&q=80)' }}><div className="w-full max-w-md rounded-3xl bg-white p-7 shadow-2xl sm:p-10"><div className="mb-8 flex items-center gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-red-500 text-white"><Shield className="h-6 w-6" /></div><div><p className="font-bold text-slate-900">ResQNow</p><p className="text-[10px] text-slate-500">Responder Personnel Portal</p></div></div><p className="text-xs font-bold uppercase tracking-[.18em] text-teal-600">Authorized access</p><h1 className="mt-2 text-2xl font-bold text-slate-900">{mode === 'login' ? 'Responder Login' : 'Create responder account'}</h1><p className="mt-2 text-sm text-slate-500">{mode === 'login' ? 'Sign in to open your field workspace.' : 'Register your personnel account for field operations.'}</p>{error && <p className="mt-5 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">{error}</p>}{message && <p className="mt-5 rounded-xl border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs text-emerald-700">{message}</p>}<form onSubmit={submit} className="mt-7 space-y-4">{mode === 'signup' && <label className="block text-xs font-semibold text-slate-700">Full name<input value={name} onChange={(event) => setName(event.target.value)} className="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-teal-500" placeholder="Juan Dela Cruz" /></label>}<label className="block text-xs font-semibold text-slate-700">Email address<input value={email} onChange={(event) => setEmail(event.target.value)} type="email" className="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-teal-500" /></label><label className="block text-xs font-semibold text-slate-700">Password<input value={password} onChange={(event) => setPassword(event.target.value)} type="password" className="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-teal-500" /></label><button className="w-full rounded-xl bg-gradient-to-r from-teal-500 to-blue-600 py-3 text-sm font-bold text-white shadow-lg shadow-teal-500/20">{mode === 'login' ? 'Sign in' : 'Create account'}</button></form><div className="mt-6 text-center"><button type="button" onClick={() => { setMode(mode === 'login' ? 'signup' : 'login'); setError(''); setMessage(''); }} className="text-xs font-bold text-teal-600 hover:text-teal-700">{mode === 'login' ? 'New responder? Sign up' : 'Already have an account? Sign in'}</button></div>{mode === 'login' && <div className="mt-6 rounded-2xl border border-teal-100 bg-teal-50 p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-teal-700">Mock responder account</p><p className="mt-2 text-xs text-slate-700"><strong>rescuer@test.com</strong> · password <strong>rescuer123</strong></p></div>}</div></div>;
}

function ResponderLogin({ onLogin }) {
  const [email, setEmail] = useState('rescuer@test.com'); const [password, setPassword] = useState('rescuer123'); const [error, setError] = useState('');
  return <div className="responder-shell flex min-h-screen items-center justify-center bg-cover bg-center p-4" style={{ backgroundImage: 'linear-gradient(120deg, rgba(15,118,110,.88), rgba(30,58,95,.86)), url(https://images.unsplash.com/photo-1580674684081-7617fbf3d745?w=1600&q=80)' }}><div className="grid w-full max-w-4xl overflow-hidden rounded-3xl bg-white shadow-2xl md:grid-cols-[.9fr_1.1fr]"><div className="hidden bg-slate-900 p-10 text-white md:block"><div className="mb-16 flex items-center gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-red-500"><Shield className="h-6 w-6" /></div><div><p className="font-bold">ResQNow</p><p className="text-[10px] text-slate-400">Barangay Camunatan</p></div></div><p className="mb-3 text-xs font-bold uppercase tracking-[.2em] text-teal-300">Field operations</p><h1 className="text-4xl font-bold leading-tight">Respond with clarity when every minute matters.</h1><p className="mt-5 text-sm leading-7 text-slate-300">A focused workspace for assigned reports, field progress, checklists, and direct admin coordination.</p><div className="mt-12 grid grid-cols-2 gap-3">{[['18', 'Active reports'], ['04', 'High priority']].map(([value, label]) => <div key={label} className="rounded-2xl border border-white/10 bg-white/5 p-4"><p className="text-2xl font-bold">{value}</p><p className="mt-1 text-[10px] uppercase tracking-wider text-slate-400">{label}</p></div>)}</div></div><div className="p-7 sm:p-10"><div className="mb-8 flex items-center gap-3 md:hidden"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-red-500 text-white"><Shield className="h-5 w-5" /></div><div><p className="font-bold text-slate-900">ResQNow</p><p className="text-[10px] text-slate-500">Personnel Portal</p></div></div><p className="text-xs font-bold uppercase tracking-[.18em] text-teal-600">Authorized access</p><h2 className="mt-2 text-2xl font-bold text-slate-900">Responder Login</h2><p className="mt-2 text-sm text-slate-500">Sign in to open your field workspace.</p>{error && <div className="mt-5 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">{error}</div>}<form className="mt-7 space-y-5" onSubmit={(event) => { event.preventDefault(); if (!onLogin(email, password)) setError('Use the mock responder account shown below.'); }}><label className="block text-xs font-semibold text-slate-700">Email address<input value={email} onChange={(event) => setEmail(event.target.value)} type="email" className="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-teal-500 focus:ring-2 focus:ring-teal-100" /></label><label className="block text-xs font-semibold text-slate-700">Password<input value={password} onChange={(event) => setPassword(event.target.value)} type="password" className="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-teal-500 focus:ring-2 focus:ring-teal-100" /></label><button className="flex w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-teal-500 to-blue-600 py-3 text-sm font-bold text-white shadow-lg shadow-teal-500/20 transition hover:brightness-105"><Radio className="h-4 w-4" /> Open field dashboard</button></form><div className="mt-6 rounded-2xl border border-teal-100 bg-teal-50 p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-teal-700">Mock responder account</p><p className="mt-2 text-xs text-slate-700"><strong>rescuer@test.com</strong> · password <strong>rescuer123</strong></p><p className="mt-1 text-[10px] text-slate-500">Role: rescuer · Assigned personnel: Delos Reyes</p></div></div></div></div>;
}

function ResponderSidebar({ screen, setScreen, onLogout }) { const items = [['dashboard', Home, 'Dashboard'], ['assigned', FileText, 'Assigned reports'], ['map', Map, 'Map / navigation'], ['notifications', Bell, 'Notifications'], ['admin', SlidersHorizontal, 'Admin support']]; return <aside className="fixed inset-y-0 left-0 z-40 hidden w-64 border-r border-slate-200 bg-white md:block"><div className="flex h-16 items-center gap-3 border-b border-slate-100 px-6"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-resqnow-red text-white"><Shield className="h-5 w-5" /></div><div><p className="text-sm font-bold text-slate-900">ResQNow</p><p className="text-[10px] text-slate-500">Personnel Portal</p></div></div><div className="p-4"><p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-wider text-slate-400">Workspace</p>{items.map(([id, Icon, label]) => <button key={id} onClick={() => setScreen(id)} className={`mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-xs font-semibold transition ${screen === id ? 'bg-teal-50 text-teal-700' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800'}`}><Icon className="h-4 w-4" />{label}{id === 'notifications' && <span className="ml-auto h-2 w-2 rounded-full bg-red-500" />}</button>)}<div className="my-5 border-t border-slate-100" /><p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-wider text-slate-400">Session</p><button onClick={onLogout} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-xs font-semibold text-slate-500 hover:bg-red-50 hover:text-red-600"><LogOut className="h-4 w-4" />Sign out</button></div><div className="absolute bottom-5 left-5 right-5 rounded-2xl bg-slate-900 p-4 text-white"><div className="flex items-center gap-2"><Activity className="h-4 w-4 text-emerald-400" /><span className="text-[10px] font-bold uppercase tracking-wider">Field network</span></div><p className="mt-2 text-[11px] text-slate-400">Connected · last sync just now</p></div></aside>; }
function ResponderBottomNav({ screen, setScreen }) { return <nav className="fixed bottom-0 left-0 right-0 z-50 border-t border-slate-200 bg-white shadow-[0_-4px_20px_rgba(0,0,0,0.06)]"><div className="mx-auto grid h-[70px] max-w-lg grid-cols-5 items-end pb-2"><NavItem screen={screen} onClick={() => setScreen('dashboard')} icon={Home} label="Home" /><NavItem screen={screen} onClick={() => setScreen('map')} icon={MapPin} label="Map" /><div className="relative flex h-full flex-col items-center justify-end"><button type="button" onClick={() => setScreen('respond')} aria-label="Respond to an incident" className="absolute -top-6 flex h-[62px] w-[62px] items-center justify-center rounded-full border-4 border-white bg-gradient-to-br from-red-500 to-orange-500 text-white shadow-[0_8px_24px_rgba(239,68,68,0.45)] ring-2 ring-red-100 transition-transform active:scale-95"><CirclePlus className="h-8 w-8" /></button><span className="mb-0.5 text-[10px] font-bold text-resqnow-red">Respond</span></div><NavItem screen={screen} onClick={() => setScreen('notifications')} icon={Bell} label="Updates" /><NavItem screen={screen} onClick={() => setScreen('settings')} icon={Settings} label="Settings" /></div></nav>; }

function NavItem({ screen, onClick, icon: Icon, label }) { const active = (label === 'Home' && screen === 'dashboard') || (label === 'Updates' && screen === 'notifications') || (label === 'Map' && screen === 'map') || (label === 'Settings' && screen === 'settings') || (label === 'Respond' && screen === 'respond'); return <button type="button" onClick={onClick} className={`flex h-full min-w-0 flex-col items-center justify-end gap-1 pb-0.5 text-[9px] font-medium transition-colors ${active ? 'text-resqnow-red' : 'text-slate-400 hover:text-slate-600'}`}><Icon className="h-5 w-5" /><span className="whitespace-nowrap">{label}</span></button>; }

function RespondScreen({ reports, openReport }) { const activeReports = reports.filter((report) => !['Resolved', 'False/invalid after checking'].includes(report.status)).sort((a, b) => (a.priority === 'High' ? -1 : b.priority === 'High' ? 1 : 0)); return <div><PageHeading eyebrow="Field response" title="Respond" description="Choose an active incident to open its details and send a progress update." /><div className="space-y-3">{activeReports.map((report) => <section key={report.id} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2"><p className="text-sm font-bold text-slate-900">{report.id}</p><span className={`rounded-full border px-2 py-0.5 text-[9px] font-bold ${priorityClass(report.priority)}`}>{report.priority}</span></div><p className="mt-1 text-xs font-semibold text-slate-700">{report.type}</p><p className="mt-1 flex items-center gap-1 text-[10px] text-slate-500"><MapPin className="h-3 w-3" />{report.location}</p></div><span className={`rounded-full px-2 py-1 text-[9px] font-bold ${statusClass(report.status)}`}>{report.status}</span></div><div className="mt-4 flex gap-2"><button type="button" onClick={() => openReport(report.id)} className="flex-1 rounded-xl bg-teal-600 py-2.5 text-xs font-bold text-white">Open report</button><button type="button" onClick={() => openReport(report.id, 'map')} className="rounded-xl border border-slate-200 px-3 text-slate-500" aria-label={`Open map for ${report.id}`}><Navigation className="h-4 w-4" /></button></div></section>)}</div></div>; }

function ResponderSettings({ user, onLogout }) { return <div><PageHeading eyebrow="Account" title="Settings" description="Manage your responder session and field profile." /><section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center gap-4 border-b border-slate-100 p-5"><div className="flex h-14 w-14 items-center justify-center rounded-full bg-gradient-to-br from-teal-500 to-blue-600 text-lg font-bold text-white">DR</div><div><p className="text-sm font-bold text-slate-900">{user.name}</p><p className="mt-1 text-xs text-slate-500">{user.email}</p><p className="mt-1 text-[10px] font-semibold uppercase tracking-wider text-teal-600">{user.role} · {user.id}</p></div></div><div className="divide-y divide-slate-100"><div className="flex items-center justify-between p-4"><div><p className="text-xs font-semibold text-slate-700">Barangay assignment</p><p className="mt-1 text-[10px] text-slate-400">Barangay Camunatan</p></div><Shield className="h-4 w-4 text-teal-600" /></div><div className="flex items-center justify-between p-4"><div><p className="text-xs font-semibold text-slate-700">Session status</p><p className="mt-1 text-[10px] text-emerald-600">Active responder session</p></div><span className="h-2 w-2 rounded-full bg-emerald-500" /></div></div></section><button type="button" onClick={onLogout} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl border border-red-200 bg-red-50 py-3 text-xs font-bold text-red-700 hover:bg-red-100"><LogOut className="h-4 w-4" />Log out</button></div>; }

function PageHeading({ eyebrow, title, description, action }) { return <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-[10px] font-bold uppercase tracking-[.18em] text-teal-600">{eyebrow}</p><h2 className="mt-1 text-2xl font-bold tracking-tight text-slate-900">{title}</h2>{description && <p className="mt-1 max-w-2xl text-xs text-slate-500">{description}</p>}</div>{action}</div>; }
function StatCard({ icon: Icon, label, value, tone = 'teal' }) { return <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-center justify-between"><div className={`flex h-9 w-9 items-center justify-center rounded-xl ${tone === 'red' ? 'bg-red-50 text-red-600' : tone === 'amber' ? 'bg-amber-50 text-amber-600' : tone === 'blue' ? 'bg-blue-50 text-blue-600' : 'bg-teal-50 text-teal-600'}`}><Icon className="h-4 w-4" /></div><span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Today</span></div><p className="mt-4 text-2xl font-bold text-slate-900">{value}</p><p className="mt-1 text-xs text-slate-500">{label}</p></div>; }
function ReportRow({ report, openReport }) { return <div className="flex flex-col gap-4 border-b border-slate-100 p-4 last:border-0 sm:flex-row sm:items-center sm:justify-between"><div className="flex min-w-0 items-start gap-3"><div className={`mt-1 flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ${report.priority === 'High' ? 'bg-red-50 text-red-600' : 'bg-teal-50 text-teal-600'}`}><AlertTriangle className="h-4 w-4" /></div><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-bold text-slate-900">{report.id}</p><span className={`rounded-full border px-2 py-0.5 text-[9px] font-bold ${priorityClass(report.priority)}`}>{report.priority}</span><span className={`rounded-full px-2 py-0.5 text-[9px] font-bold ${statusClass(report.status)}`}>{report.status}</span></div><p className="mt-1 text-xs font-semibold text-slate-700">{report.type}</p><p className="mt-1 flex items-center gap-1 text-[11px] text-slate-500"><MapPin className="h-3 w-3" />{report.location}</p><p className="mt-1 text-[10px] text-slate-400">Assigned {report.assignedAt}</p></div></div><div className="flex items-center gap-2 sm:shrink-0"><button onClick={() => openReport(report.id)} className="flex items-center gap-1 rounded-lg bg-teal-600 px-3 py-2 text-[10px] font-bold text-white hover:bg-teal-700">View details<ChevronRight className="h-3 w-3" /></button><button onClick={() => openReport(report.id, 'map')} className="rounded-lg border border-slate-200 p-2 text-slate-500 hover:bg-slate-50" aria-label="Open map"><Navigation className="h-4 w-4" /></button></div></div>; }

function Dashboard({ reports, openReport, setScreen }) { const high = reports.filter((r) => r.priority === 'High'); const active = reports.filter((r) => !['Resolved', 'False/invalid after checking'].includes(r.status)); return <div><PageHeading eyebrow="Good morning, Delos Reyes" title="Field Dashboard" description="Your assigned response queue, instructions, and field readiness at a glance." action={<button onClick={() => setScreen('assigned')} className="flex items-center justify-center gap-2 rounded-xl bg-teal-600 px-4 py-3 text-xs font-bold text-white shadow-lg shadow-teal-600/15 hover:bg-teal-700"><FileText className="h-4 w-4" />Open assigned reports</button>} /><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><StatCard icon={FileText} label="Assigned reports" value={reports.length} /><StatCard icon={AlertTriangle} label="High priority" value={high.length} tone="red" /><StatCard icon={Activity} label="In progress" value={active.length} tone="blue" /><StatCard icon={CheckCircle2} label="Resolved this week" value="12" tone="amber" /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.4fr_.8fr]"><section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between border-b border-slate-100 px-4 py-4"><div><h3 className="text-sm font-bold text-slate-900">High priority reports</h3><p className="mt-1 text-[10px] text-slate-400">Respond in order of field risk</p></div><button onClick={() => setScreen('assigned')} className="text-[10px] font-bold text-teal-600">View queue</button></div>{high.map((report) => <ReportRow key={report.id} report={report} openReport={openReport} />)}</section><section className="rounded-2xl border border-slate-200 bg-slate-900 p-5 text-white shadow-sm"><div className="flex items-center justify-between"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-white/10"><MessageSquare className="h-4 w-4 text-teal-300" /></div><span className="rounded-full bg-emerald-400/15 px-2 py-1 text-[9px] font-bold text-emerald-300">NEW</span></div><p className="mt-6 text-[10px] font-bold uppercase tracking-[.18em] text-teal-300">Admin instruction</p><h3 className="mt-2 text-lg font-bold">Bring flotation support</h3><p className="mt-2 text-xs leading-6 text-slate-300">EM-001 has water above knee level. Coordinate with Rescue Team Alpha before entering the area.</p><div className="mt-6 flex items-center gap-2 border-t border-white/10 pt-4 text-[10px] text-slate-400"><Clock3 className="h-3.5 w-3.5" />Admin Delos Reyes · 8:52 AM</div></section></div><section className="mt-6 rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="border-b border-slate-100 px-4 py-4"><h3 className="text-sm font-bold text-slate-900">Recent activity</h3></div><div className="grid gap-3 p-4 sm:grid-cols-3">{['Priority alert received for EM-001', 'Medical hotline suggested for EM-002', 'Checklist saved for NE-003'].map((text, index) => <div key={text} className="flex gap-3 rounded-xl bg-slate-50 p-3"><div className="mt-0.5 h-2 w-2 shrink-0 rounded-full bg-teal-500" /><div><p className="text-xs font-semibold text-slate-700">{text}</p><p className="mt-1 text-[10px] text-slate-400">{index + 1} hour{index ? 's' : ''} ago</p></div></div>)}</div></section></div>; }

function AssignedReports({ reports, openReport, setScreen }) { const [filter, setFilter] = useState('All'); const filtered = reports.filter((r) => filter === 'All' || r.priority === filter || r.status === filter); return <div><PageHeading eyebrow="Response queue" title="Assigned Reports" description="Reports assigned to Responder Delos Reyes. Use the field actions to keep admin updated." action={<button onClick={() => setScreen('map')} className="flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-bold text-slate-700 shadow-sm"><Map className="h-4 w-4 text-teal-600" />Open map view</button>} /><div className="mb-4 flex flex-wrap gap-2">{['All', 'High', 'Medium', 'Low', 'On the way', 'Arrived at location'].map((item) => <button key={item} onClick={() => setFilter(item)} className={`rounded-full border px-3 py-2 text-[10px] font-bold ${filter === item ? 'border-teal-600 bg-teal-600 text-white' : 'border-slate-200 bg-white text-slate-500'}`}>{item}</button>)}</div><div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">{filtered.map((report) => <ReportRow key={report.id} report={report} openReport={openReport} />)}{filtered.length === 0 && <div className="p-10 text-center text-sm text-slate-500">No reports match this filter.</div>}</div></div>; }

function ReportDetails({ report, setScreen, openModal, toggleChecklist }) { const hotline = hotlines[report.type] || hotlines['Public Safety']; return <div><button onClick={() => setScreen('assigned')} className="mb-5 flex items-center gap-2 text-xs font-bold text-slate-500 hover:text-teal-600"><ArrowLeft className="h-4 w-4" />Back to assigned reports</button><PageHeading eyebrow={`Report ${report.id}`} title={report.type} description={`${report.location} · Assigned ${report.assignedAt}`} action={<button onClick={() => openModal('update')} className="flex items-center justify-center gap-2 rounded-xl bg-teal-600 px-4 py-3 text-xs font-bold text-white shadow-lg shadow-teal-600/15"><RefreshCw className="h-4 w-4" />Update status</button>} /><div className="grid gap-6 lg:grid-cols-[1.35fr_.8fr]"><div className="space-y-6"><section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><span className={`rounded-full border px-3 py-1 text-[10px] font-bold ${priorityClass(report.priority)}`}>{report.priority} priority</span><span className={`rounded-full px-3 py-1 text-[10px] font-bold ${statusClass(report.status)}`}>{report.status}</span></div><span className="text-[10px] font-semibold text-slate-400">Score {report.score}/8</span></div><h3 className="mt-5 text-sm font-bold text-slate-900">Original resident report</h3><p className="mt-2 rounded-xl bg-slate-50 p-4 text-sm leading-6 text-slate-600">{report.description}</p><div className="mt-4 grid gap-4 sm:grid-cols-2"><InfoItem icon={MapPin} label="Pinned location" value={`${report.location} · ${report.landmark}`} /><InfoItem icon={Phone} label="Contact person" value={`${report.contactName} · ${report.contact}`} /><InfoItem icon={Shield} label="Assigned team" value={report.team} /><InfoItem icon={FileText} label="Barangay assessment" value={report.assessment} /></div></section><section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><h3 className="text-sm font-bold text-slate-900">Action checklist</h3><p className="mt-1 text-[10px] text-slate-400">Each item records who checked it and when.</p></div><ClipboardCheck className="h-5 w-5 text-teal-600" /></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{checklistItems.map((item) => { const checked = Boolean(report.checklist[item]); return <button key={item} onClick={() => toggleChecklist(item)} className={`flex items-center gap-3 rounded-xl border p-3 text-left transition ${checked ? 'border-emerald-200 bg-emerald-50' : 'border-slate-100 bg-slate-50 hover:border-teal-200'}`}><span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-md border ${checked ? 'border-emerald-500 bg-emerald-500 text-white' : 'border-slate-300 bg-white'}`}>{checked && <Check className="h-3.5 w-3.5" />}</span><span className="min-w-0"><span className="block text-xs font-semibold text-slate-700">{item}</span>{checked && <span className="mt-0.5 block text-[9px] text-emerald-700">{typeof report.checklist[item] === 'object' ? `${report.checklist[item].by} · ${report.checklist[item].time}` : 'Saved'}</span>}</span></button>; })}</div></section></div><div className="space-y-6"><section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="map-surface relative h-40"><div className="absolute left-[48%] top-[42%] flex h-12 w-12 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-red-500/20"><div className="flex h-7 w-7 items-center justify-center rounded-full bg-red-600 text-white shadow-lg"><MapPin className="h-4 w-4" /></div></div><span className="absolute left-3 top-3 rounded-lg bg-white/90 px-2 py-1 text-[9px] font-bold text-slate-600 shadow">PINNED LOCATION</span></div><div className="flex items-center justify-between p-4"><div><p className="text-xs font-bold text-slate-900">Navigate to incident</p><p className="mt-1 text-[10px] text-slate-500">{report.landmark}</p></div><button onClick={() => setScreen('map')} className="flex items-center gap-1 rounded-lg bg-slate-900 px-3 py-2 text-[10px] font-bold text-white"><Navigation className="h-3.5 w-3.5" />Open map</button></div></section><section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center gap-2"><Phone className="h-4 w-4 text-teal-600" /><h3 className="text-sm font-bold text-slate-900">Suggested hotline</h3></div><p className="mt-3 text-sm font-semibold text-slate-700">{hotline[0]}</p><p className="mt-1 text-xs text-slate-500">{hotline[1]}</p><button className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl border border-teal-200 bg-teal-50 py-2.5 text-[10px] font-bold text-teal-700"><Phone className="h-3.5 w-3.5" />Call hotline</button></section><section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h3 className="text-sm font-bold text-slate-900">Status history</h3><div className="mt-4 space-y-4">{report.history.map((event, index) => <div key={`${event.status}-${index}`} className="relative flex gap-3"><div className="relative flex w-4 justify-center"><span className="z-10 mt-1.5 h-2.5 w-2.5 rounded-full bg-teal-500 ring-4 ring-teal-50" />{index < report.history.length - 1 && <span className="absolute top-4 h-full w-px bg-teal-100" />}</div><div className="pb-1"><p className="text-xs font-bold text-slate-700">{event.status}</p><p className="mt-0.5 text-[10px] text-slate-400">{event.by} · {event.time}</p>{event.remarks && <p className="mt-1 text-[11px] text-slate-500">{event.remarks}</p>}</div></div>)}</div></section></div></div></div>; }
function InfoItem({ icon: Icon, label, value }) { return <div className="flex gap-2"><Icon className="mt-0.5 h-4 w-4 shrink-0 text-teal-600" /><div><p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">{label}</p><p className="mt-1 text-xs leading-5 text-slate-700">{value}</p></div></div>; }

function UpdateModal({ report, onClose, onSave }) { const [status, setStatus] = useState(report.status); const [remarks, setRemarks] = useState(''); const [proof, setProof] = useState(''); const [error, setError] = useState(''); return <div className="fixed inset-0 z-50 flex items-end justify-center bg-slate-900/50 p-0 backdrop-blur-sm sm:items-center sm:p-4"><div className="w-full max-w-lg rounded-t-3xl bg-white p-6 shadow-2xl sm:rounded-3xl"><div className="flex items-start justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.18em] text-teal-600">Field progress</p><h2 className="mt-1 text-xl font-bold text-slate-900">Update {report.id}</h2></div><button onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-slate-50" aria-label="Close"><X className="h-5 w-5" /></button></div><div className="mt-6 space-y-5"><label className="block text-xs font-semibold text-slate-700">New status<select value={status} onChange={(event) => setStatus(event.target.value)} className="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-sm outline-none focus:border-teal-500">{updateOptions.map((option) => <option key={option}>{option}</option>)}</select></label><label className="block text-xs font-semibold text-slate-700">Remarks <span className="font-normal text-red-500">Required</span><textarea value={remarks} onChange={(event) => { setRemarks(event.target.value); setError(''); }} rows="4" placeholder="Describe what happened in the field..." className="mt-2 w-full resize-none rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-sm outline-none focus:border-teal-500" /></label><label className="block text-xs font-semibold text-slate-700">Proof / photo <span className="font-normal text-slate-400">Optional</span><input type="file" accept="image/*" onChange={(event) => setProof(event.target.files?.[0]?.name || '')} className="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-xs outline-none focus:border-teal-500" /></label>{error && <p className="text-xs text-red-600">{error}</p>}<div className="grid grid-cols-2 gap-3"><div className="rounded-xl bg-slate-50 p-3"><p className="text-[9px] font-bold uppercase tracking-wider text-slate-400">Updated by</p><p className="mt-1 text-xs font-semibold text-slate-700">Delos Reyes</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[9px] font-bold uppercase tracking-wider text-slate-400">Date / time</p><p className="mt-1 text-xs font-semibold text-slate-700">Automatic on save</p></div></div><button onClick={() => { if (!onSave(status, remarks, proof)) setError('Remarks are required before saving the progress update.'); }} className="w-full rounded-xl bg-teal-600 py-3 text-sm font-bold text-white hover:bg-teal-700">Save progress update</button></div></div></div>; }

function DashboardMapOverview({ reports, openReport }) { return <section className="responder-dashboard-map mt-5 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between border-b border-slate-100 px-4 py-3.5"><div><h2 className="text-sm font-bold text-slate-900">Map / Navigation</h2><p className="mt-0.5 text-[10px] text-slate-400">Assigned incident locations</p></div><button type="button" onClick={() => openReport(reports[0].id, 'map')} className="flex items-center gap-1 text-[10px] font-bold text-teal-600">Open map<ChevronRight className="h-3.5 w-3.5" /></button></div><div className="map-surface relative h-48"><div className="absolute inset-0 opacity-50"><div className="absolute left-1/4 top-0 h-full w-px rotate-12 bg-white" /><div className="absolute left-2/3 top-0 h-full w-px -rotate-45 bg-white" /><div className="absolute top-1/3 h-px w-full rotate-6 bg-white" /><div className="absolute top-2/3 h-px w-full -rotate-12 bg-white" /></div>{reports.map((report, index) => <button key={report.id} type="button" onClick={() => openReport(report.id)} className="absolute flex -translate-x-1/2 -translate-y-1/2 flex-col items-center" style={{ left: `${24 + (index * 19) % 58}%`, top: `${27 + (index * 23) % 52}%` }}><span className={`flex h-9 w-9 items-center justify-center rounded-full border-4 border-white text-white shadow-lg ${report.priority === 'High' ? 'bg-red-600' : 'bg-teal-600'}`}><MapPin className="h-4 w-4" /></span><span className="mt-1 rounded-md bg-white px-1.5 py-0.5 text-[9px] font-bold text-slate-700 shadow">{report.id}</span></button>)}</div></section>; }

function MapView({ reports, selectedId, openReport }) { return <div><PageHeading eyebrow="Live response map" title="Map / Navigation" description="Assigned incident pins shared with the responder workflow." action={<button className="flex items-center gap-2 rounded-xl bg-slate-900 px-4 py-3 text-xs font-bold text-white"><Navigation className="h-4 w-4" />Open device navigation</button>} /><div className="grid gap-6 lg:grid-cols-[1.4fr_.7fr]"><div className="map-surface relative min-h-[480px] overflow-hidden rounded-2xl border border-slate-200 shadow-sm"><div className="absolute inset-0 opacity-50"><div className="absolute left-1/4 top-0 h-full w-px rotate-12 bg-white" /><div className="absolute left-2/3 top-0 h-full w-px -rotate-45 bg-white" /><div className="absolute top-1/3 h-px w-full rotate-6 bg-white" /><div className="absolute top-2/3 h-px w-full -rotate-12 bg-white" /></div>{reports.map((report, index) => <button key={report.id} onClick={() => openReport(report.id)} className={`absolute flex -translate-x-1/2 -translate-y-1/2 flex-col items-center ${selectedId === report.id ? 'z-20' : 'z-10'}`} style={{ left: `${24 + (index * 19) % 58}%`, top: `${27 + (index * 23) % 52}%` }}><span className={`flex h-10 w-10 items-center justify-center rounded-full border-4 border-white shadow-lg ${report.priority === 'High' ? 'bg-red-600' : 'bg-teal-600'} text-white`}><MapPin className="h-5 w-5" /></span><span className="mt-1 rounded-md bg-white px-2 py-1 text-[9px] font-bold text-slate-700 shadow">{report.id}</span></button>)}<div className="absolute bottom-4 left-4 rounded-xl bg-white/90 p-3 text-[10px] font-semibold text-slate-600 shadow"><div className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full bg-red-600" />High priority</div><div className="mt-2 flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full bg-teal-600" />Assigned incident</div></div></div><section className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="border-b border-slate-100 p-4"><h3 className="text-sm font-bold text-slate-900">Assigned locations</h3><p className="mt-1 text-[10px] text-slate-400">Select a pin to open full details.</p></div>{reports.map((report) => <button key={report.id} onClick={() => openReport(report.id)} className="flex w-full items-start gap-3 border-b border-slate-100 p-4 text-left last:border-0 hover:bg-slate-50"><MapPin className={`mt-0.5 h-4 w-4 ${report.priority === 'High' ? 'text-red-600' : 'text-teal-600'}`} /><div className="min-w-0"><p className="text-xs font-bold text-slate-800">{report.id} · {report.type}</p><p className="mt-1 truncate text-[10px] text-slate-500">{report.location}</p></div><ChevronRight className="ml-auto h-4 w-4 shrink-0 text-slate-300" /></button>)}</section></div></div>; }

function InteractiveNotifications({ openReport }) { const [readIds, setReadIds] = useState(() => JSON.parse(localStorage.getItem('resqnow_read_notifications') || '[]')); const notifications = [{ title: 'Priority changed to High', message: 'Admin added 6 checklist risk factors to EM-001.', time: '8 min ago', id: 'EM-001', icon: AlertTriangle, tone: 'red' }, { title: 'New admin instruction', message: 'Bring flotation support before entering Purok 2.', time: '14 min ago', id: 'EM-001-instruction', reportId: 'EM-001', icon: MessageSquare, tone: 'teal' }, { title: 'Hotline suggestion', message: 'Hospital / Ambulance is suggested for EM-002.', time: '1 hr ago', id: 'EM-002-hotline', reportId: 'EM-002', icon: Phone, tone: 'blue' }, { title: 'Checklist saved', message: 'Your field checklist for NE-003 was saved.', time: '2 hrs ago', id: 'NE-003-checklist', reportId: 'NE-003', icon: ClipboardCheck, tone: 'amber' }]; const saveReadIds = (ids) => { setReadIds(ids); localStorage.setItem('resqnow_read_notifications', JSON.stringify(ids)); }; const markRead = (notification) => { const nextIds = readIds.includes(notification.id) ? readIds : [...readIds, notification.id]; saveReadIds(nextIds); openReport(notification.reportId || notification.id, 'details', 'notifications'); }; return <div><PageHeading eyebrow="Stay coordinated" title="Responder Notifications" description="Admin instructions and report updates connected to your assigned incidents." action={<button type="button" onClick={() => saveReadIds(notifications.map((notification) => notification.id))} className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-bold text-slate-700"><Check className="h-4 w-4" />Mark all read</button>} /><div className="space-y-3">{notifications.map(({ title, message, time, id, icon: Icon, tone, reportId }) => <button key={id} type="button" onClick={() => markRead({ id, reportId })} className="flex w-full items-start gap-4 rounded-2xl border border-slate-200 bg-white p-4 text-left shadow-sm hover:border-teal-200"><div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${tone === 'red' ? 'bg-red-50 text-red-600' : tone === 'amber' ? 'bg-amber-50 text-amber-600' : tone === 'blue' ? 'bg-blue-50 text-blue-600' : 'bg-teal-50 text-teal-600'}`}><Icon className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-bold text-slate-900">{title}</p>{!readIds.includes(id) && <span className="h-1.5 w-1.5 rounded-full bg-red-500" />}</div><p className="mt-1 text-xs leading-5 text-slate-500">{message}</p><p className="mt-2 text-[10px] font-semibold text-slate-400">{reportId || id} · {time}</p></div><ChevronRight className="mt-2 h-4 w-4 text-slate-300" /></button>)}</div></div>; }

function Notifications({ openReport }) { const notifications = [{ title: 'Priority changed to High', message: 'Admin added 6 checklist risk factors to EM-001.', time: '8 min ago', id: 'EM-001', icon: AlertTriangle, tone: 'red' }, { title: 'New admin instruction', message: 'Bring flotation support before entering Purok 2.', time: '14 min ago', id: 'EM-001', icon: MessageSquare, tone: 'teal' }, { title: 'Hotline suggestion', message: 'Hospital / Ambulance is suggested for EM-002.', time: '1 hr ago', id: 'EM-002', icon: Phone, tone: 'blue' }, { title: 'Checklist saved', message: 'Your field checklist for NE-003 was saved.', time: '2 hrs ago', id: 'NE-003', icon: ClipboardCheck, tone: 'amber' }]; return <div><PageHeading eyebrow="Stay coordinated" title="Responder Notifications" description="Admin instructions, priority triggers, and updates connected to your assigned reports." action={<button className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-bold text-slate-700"><Check className="h-4 w-4" />Mark all read</button>} /><div className="space-y-3">{notifications.map(({ title, message, time, id, icon: Icon, tone }) => <button key={`${title}-${id}`} onClick={() => openReport(id)} className="flex w-full items-start gap-4 rounded-2xl border border-slate-200 bg-white p-4 text-left shadow-sm hover:border-teal-200"><div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${tone === 'red' ? 'bg-red-50 text-red-600' : tone === 'amber' ? 'bg-amber-50 text-amber-600' : tone === 'blue' ? 'bg-blue-50 text-blue-600' : 'bg-teal-50 text-teal-600'}`}><Icon className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-bold text-slate-900">{title}</p><span className="h-1.5 w-1.5 rounded-full bg-red-500" /></div><p className="mt-1 text-xs leading-5 text-slate-500">{message}</p><p className="mt-2 text-[10px] font-semibold text-slate-400">{id} · {time}</p></div><ChevronRight className="mt-2 h-4 w-4 text-slate-300" /></button>)}</div></div>; }

function AdminSupport({ reports, showNotice }) { const [tab, setTab] = useState('prioritization'); const [checks, setChecks] = useState({}); const [priorityRemarks, setPriorityRemarks] = useState(''); const [search, setSearch] = useState(''); const score = Object.values(checks).filter(Boolean).length; const suggested = score >= 5 ? 'High' : score >= 3 ? 'Medium' : 'Low'; const byPriority = { High: reports.filter((r) => r.priority === 'High').length, Medium: reports.filter((r) => r.priority === 'Medium').length, Low: reports.filter((r) => r.priority === 'Low').length }; return <div><PageHeading eyebrow="Admin support · Delos Reyes" title="Prioritization & Insights" description="Checklist-based triage connected to responder assignments, map pins, hotlines, and notifications." /><div className="mb-6 flex gap-1 overflow-x-auto rounded-xl border border-slate-200 bg-white p-1 shadow-sm">{[['prioritization', SlidersHorizontal, 'Prioritization'], ['map', Map, 'Map view'], ['hotlines', Phone, 'Hotline support'], ['analytics', BarChart3, 'Analytics']].map(([id, Icon, label]) => <button key={id} onClick={() => setTab(id)} className={`flex shrink-0 items-center gap-2 rounded-lg px-4 py-2.5 text-xs font-bold ${tab === id ? 'bg-teal-600 text-white' : 'text-slate-500 hover:bg-slate-50'}`}><Icon className="h-4 w-4" />{label}</button>)}</div>{tab === 'prioritization' && <div className="grid gap-6 lg:grid-cols-[1fr_.85fr]"><section className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="border-b border-slate-100 p-5"><div className="flex items-center justify-between"><div><h3 className="text-sm font-bold text-slate-900">Priority queue</h3><p className="mt-1 text-[10px] text-slate-400">High risk reports trigger responder alerts.</p></div><div className="flex gap-1">{Object.entries(byPriority).map(([key, value]) => <span key={key} className={`rounded-md px-2 py-1 text-[9px] font-bold ${priorityClass(key)}`}>{key} {value}</span>)}</div></div><div className="relative mt-4"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search report or location" className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2.5 pl-9 pr-3 text-xs outline-none focus:border-teal-500" /></div></div>{reports.filter((r) => `${r.id} ${r.location}`.toLowerCase().includes(search.toLowerCase())).map((report) => <div key={report.id} className="flex items-center justify-between gap-3 border-b border-slate-100 p-4 last:border-0"><div><div className="flex items-center gap-2"><p className="text-xs font-bold text-slate-800">{report.id}</p><span className={`rounded-full border px-2 py-0.5 text-[9px] font-bold ${priorityClass(report.priority)}`}>{report.priority}</span></div><p className="mt-1 text-[10px] text-slate-500">{report.type} · {report.purok}</p></div><button onClick={() => showNotice(`${report.id} opened for priority review.`)} className="rounded-lg border border-slate-200 px-3 py-2 text-[10px] font-bold text-slate-600 hover:bg-slate-50">Review</button></div>)}</section><section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><h3 className="text-sm font-bold text-slate-900">Priority checklist</h3><p className="mt-1 text-[10px] text-slate-400">Score {score}/8 · Suggested <strong>{suggested}</strong></p></div><Zap className="h-5 w-5 text-amber-500" /></div><div className="mt-4 space-y-2">{priorityChecks.map((item) => <label key={item} className="flex cursor-pointer items-center gap-3 rounded-xl bg-slate-50 p-3"><input type="checkbox" checked={Boolean(checks[item])} onChange={(event) => setChecks({ ...checks, [item]: event.target.checked })} className="h-4 w-4 rounded border-slate-300 text-teal-600" /><span className="text-xs font-semibold text-slate-700">{item}</span></label>)}</div><textarea value={priorityRemarks} onChange={(event) => setPriorityRemarks(event.target.value)} placeholder="Required remarks or proof for a priority change" rows="3" className="mt-4 w-full resize-none rounded-xl border border-slate-200 bg-slate-50 p-3 text-xs outline-none focus:border-teal-500" /><button onClick={() => priorityRemarks.trim() ? showNotice(`Priority suggestion ${suggested} recorded by Delos Reyes.`) : showNotice('Add remarks or proof before changing priority.')} className="mt-3 w-full rounded-xl bg-slate-900 py-3 text-xs font-bold text-white">Save priority assessment</button></section></div>}{tab === 'map' && <MapView reports={reports} openReport={() => {}} />}{tab === 'hotlines' && <div className="grid gap-4 md:grid-cols-2">{Object.entries(hotlines).map(([concern, [name, number]]) => <section key={concern} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-teal-50 text-teal-600"><Phone className="h-5 w-5" /></div><div><h3 className="text-sm font-bold text-slate-900">{concern}</h3><p className="mt-1 text-[10px] text-slate-400">Suggested support channel</p></div></div><div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-4"><div><p className="text-xs font-bold text-slate-700">{name}</p><p className="mt-1 text-[11px] text-slate-500">{number}</p></div><button className="rounded-lg bg-teal-50 p-2 text-teal-700"><ExternalLink className="h-4 w-4" /></button></div></section>)}</div>}{tab === 'analytics' && <Analytics reports={reports} />}</div>; }

function Analytics({ reports }) { const statuses = [...new Set(reports.map((r) => r.status))]; const max = Math.max(...Object.values({ ...reports.reduce((acc, report) => ({ ...acc, [report.purok]: (acc[report.purok] || 0) + 1 }), {}) }), 1); return <div className="grid gap-6 lg:grid-cols-2"><section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h3 className="text-sm font-bold text-slate-900">Reports by priority</h3>{['High', 'Medium', 'Low'].map((priority) => <div key={priority} className="mt-4 flex items-center gap-3"><span className="w-14 text-[10px] font-bold text-slate-500">{priority}</span><div className="h-3 flex-1 overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full ${priority === 'High' ? 'bg-red-500' : priority === 'Medium' ? 'bg-amber-500' : 'bg-slate-400'}`} style={{ width: `${(reports.filter((r) => r.priority === priority).length / reports.length) * 100}%` }} /></div><span className="w-5 text-right text-xs font-bold text-slate-700">{reports.filter((r) => r.priority === priority).length}</span></div>)}</section><section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h3 className="text-sm font-bold text-slate-900">Reports by status</h3>{statuses.map((status) => <div key={status} className="mt-4 flex items-center justify-between"><span className="text-xs text-slate-600">{status}</span><span className="rounded-full bg-teal-50 px-2.5 py-1 text-[10px] font-bold text-teal-700">{reports.filter((r) => r.status === status).length}</span></div>)}</section><section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h3 className="text-sm font-bold text-slate-900">Emergency vs non-emergency</h3><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-xl bg-red-50 p-4"><p className="text-2xl font-bold text-red-700">{reports.filter((r) => r.emergency).length}</p><p className="mt-1 text-[10px] font-bold uppercase tracking-wider text-red-600">Emergency</p></div><div className="rounded-xl bg-slate-50 p-4"><p className="text-2xl font-bold text-slate-700">{reports.filter((r) => !r.emergency).length}</p><p className="mt-1 text-[10px] font-bold uppercase tracking-wider text-slate-500">Non-emergency</p></div></div></section><section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h3 className="text-sm font-bold text-slate-900">Reports by purok</h3>{['Purok 1', 'Purok 2', 'Purok 3'].map((purok) => <div key={purok} className="mt-4 flex items-center gap-3"><span className="w-14 text-[10px] font-bold text-slate-500">{purok}</span><div className="h-3 flex-1 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-teal-500" style={{ width: `${((reports.filter((r) => r.purok === purok).length || 0) / max) * 100}%` }} /></div><span className="w-5 text-right text-xs font-bold text-slate-700">{reports.filter((r) => r.purok === purok).length}</span></div>)}<div className="mt-5 flex gap-3 border-t border-slate-100 pt-4"><span className="rounded-lg bg-emerald-50 px-3 py-2 text-[10px] font-bold text-emerald-700">Resolved 12</span><span className="rounded-lg bg-slate-100 px-3 py-2 text-[10px] font-bold text-slate-600">Invalid 2</span></div></section></div>; }